#!/usr/bin/env python3
import json, sys, os, datetime

def ts(e):
    t = e.get('timestamp')
    if not t: return None
    try:
        return datetime.datetime.fromisoformat(t.replace('Z','+00:00'))
    except Exception:
        return None

def main(path, mode='summary'):
    entries=[]
    with open(path) as f:
        for line in f:
            line=line.strip()
            if not line: continue
            try: entries.append(json.loads(line))
            except Exception: pass
    print(f"=== {os.path.basename(path)} :: {len(entries)} entries ===")
    times=[ts(e) for e in entries if ts(e)]
    if times:
        print(f"span: {min(times).isoformat()} -> {max(times).isoformat()}  ({(max(times)-min(times)).total_seconds():.0f}s)")
    # tool call stats
    tool_calls=[]  # (uuid, name, time)
    tool_results={} # tool_use_id -> time
    assistant_msgs=0
    multi_tool=0
    for e in entries:
        m=e.get('message') or {}
        c=m.get('content')
        if e.get('type')=='assistant' and isinstance(c,list):
            tus=[b for b in c if b.get('type')=='tool_use']
            if tus:
                assistant_msgs+=1
                if len(tus)>1: multi_tool+=1
            for b in tus:
                tool_calls.append((b.get('id'), b.get('name'), ts(e)))
        if e.get('type')=='user' and isinstance(c,list):
            for b in c:
                if b.get('type')=='tool_result':
                    tool_results[b.get('tool_use_id')]=ts(e)
    print(f"assistant msgs with tools: {assistant_msgs}, of which multi-tool batches: {multi_tool}, total tool calls: {len(tool_calls)}")
    from collections import Counter
    print("tool mix:", dict(Counter(n for _,n,_ in tool_calls).most_common()))
    # durations
    durs=[]
    for tid,name,t in tool_calls:
        rt=tool_results.get(tid)
        if t and rt: durs.append((( rt-t).total_seconds(), name, t))
    durs.sort(reverse=True)
    tot=sum(d for d,_,_ in durs)
    print(f"tool exec total: {tot:.0f}s; slowest:", [(f'{d:.0f}s',n) for d,n,_ in durs[:8]])
    # gaps between a tool result and next tool call (model overhead)
    seq=sorted([(t,'call',n) for _,n,t in tool_calls if t]+[(t,'result','') for t in tool_results.values() if t])
    overhead=0.0; gaps=[]
    for i in range(len(seq)-1):
        if seq[i][1]=='result' and seq[i+1][1]=='call':
            g=(seq[i+1][0]-seq[i][0]).total_seconds()
            overhead+=g; gaps.append(g)
    gaps.sort(reverse=True)
    print(f"model round-trip overhead total: {overhead:.0f}s over {len(gaps)} gaps; largest: {[f'{g:.0f}s' for g in gaps[:6]]}")
    # consecutive same-tool singleton runs
    runs=[]; cur=None; n=0
    for e in entries:
        m=e.get('message') or {}
        c=m.get('content')
        if e.get('type')=='assistant' and isinstance(c,list):
            tus=[b for b in c if b.get('type')=='tool_use']
            if len(tus)==1:
                nm=tus[0].get('name')
                if nm==cur: n+=1
                else:
                    if cur and n>=3: runs.append((cur,n))
                    cur=nm; n=1
            elif tus:
                if cur and n>=3: runs.append((cur,n))
                cur=None; n=0
    if cur and n>=3: runs.append((cur,n))
    print("singleton runs of same tool (>=3):", runs)
    print()
    if mode=='user':
        for i,e in enumerate(entries):
            m=e.get('message') or {}
            if e.get('type')!='user': continue
            c=m.get('content')
            txt=None
            if isinstance(c,str): txt=c
            elif isinstance(c,list):
                parts=[b.get('text','') for b in c if b.get('type')=='text']
                if parts: txt='\n'.join(parts)
            if txt and not e.get('isMeta'):
                print(f"--- USER [{i}] {e.get('timestamp')} ---")
                print(txt[:4000])
                print()
    if mode=='asst':
        for i,e in enumerate(entries):
            m=e.get('message') or {}
            if e.get('type')!='assistant': continue
            c=m.get('content')
            if isinstance(c,list):
                parts=[b.get('text','') for b in c if b.get('type')=='text' and b.get('text','').strip()]
                if parts:
                    print(f"--- ASST [{i}] {e.get('timestamp')} ---")
                    print('\n'.join(parts)[:2500]); print()

if __name__=='__main__':
    main(sys.argv[1], sys.argv[2] if len(sys.argv)>2 else 'summary')

